#!/usr/bin/env bash
# AKFC — Demandes (tickets), incrément 3b : écrans de l'espace de traitement.
#  - /dashboard/tickets : onglets Ouvertes / À moi / Sans responsable / Closes, statut, responsable,
#    échéance (« réponse dans 3 j », en rouge si dépassée), alerte du nombre de demandes en retard.
#  - /dashboard/tickets/[id] : fil des messages (club à droite), réponse pré-remplie « Bonjour X, »,
#    prise en charge, transfert (personne + note obligatoire), clore / rouvrir, historique.
#  - Menus : « Demandes reçues » + pastille (nb ouvertes) dans la sidebar ET le menu utilisateur,
#    visibles des admins et des membres d'un groupe responsable (Support) — un membre Support
#    non admin voit une sidebar réduite à cette section.
#  Preuve avant commit : pnpm check (sinon TOUT est restauré).
# Usage : bash apply-tickets-increment3b.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
[ -f packages/backend/src/modules/tickets/ticketQueries.service.ts ] || { echo "ERREUR: applique d'abord apply-tickets-increment3a.sh." >&2; exit 1; }
U="apps/web/src/features/tickets/ticketUi.ts"; L="apps/web/src/app/(admin)/dashboard/tickets/page.tsx"; D="apps/web/src/app/(admin)/dashboard/tickets/[id]/page.tsx"
SB=apps/web/src/features/app-shell/ControlPanelSidebar.tsx; UM=apps/web/src/features/app-shell/UserMenu.tsx
[ -f "$U" ] && { echo "— déjà appliqué"; exit 0; }
for f in "$L" "$D"; do [ -e "$f" ] && { echo "ERREUR: $f existe déjà." >&2; exit 1; }; done
BK=/tmp/akfc_tk3b_backup; rm -rf "$BK"; mkdir -p "$BK"; cp "$SB" "$BK/sb"; cp "$UM" "$BK/um"
restore(){ cp "$BK/sb" "$SB"; cp "$BK/um" "$UM"; rm -f "$U" "$L" "$D"; rmdir "apps/web/src/app/(admin)/dashboard/tickets/[id]" "apps/web/src/app/(admin)/dashboard/tickets" apps/web/src/features/tickets 2>/dev/null || true; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }

W=/tmp/akfc_tk3b; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/nav_edit.py"
echo "== application =="
mkdir -p apps/web/src/features/tickets "apps/web/src/app/(admin)/dashboard/tickets/[id]"
echo '' | base64 -d > "$U"
echo '' | base64 -d > "$L"
echo '' | base64 -d > "$D"
echo "  ok  3 fichiers créés (ticketUi, liste, détail)"
python3 "$W/nav_edit.py" . || { restore; exit 1; }

if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi

echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"

git add "$U" "$L" "$D" "$SB" "$UM"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
feat(tickets): écrans de traitement des demandes (liste, fil, réponse, transfert, clôture)

